func reorderList(head *ListNode) {
	if head == nil || head.Next == nil {
		return
	}

	slow, fast := head, head
	for fast.Next != nil && fast.Next.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
	}

	second := slow.Next
	slow.Next = nil

	var prev *ListNode
	for second != nil {
		nxt := second.Next
		second.Next = prev
		prev = second
		second = nxt
	}

	first := head
	second = prev
	for second != nil {
		fnext := first.Next
		snext := second.Next
		first.Next = second
		second.Next = fnext
		first = fnext
		second = snext
	}
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public void reorderList(ListNode head) {
    if (head == null || head.next == null) {
      return;
    }

    ListNode slow = head;
    ListNode fast = head;
    while (fast.next != null && fast.next.next != null) {
      slow = slow.next;
      fast = fast.next.next;
    }

    ListNode second = slow.next;
    slow.next = null;

    ListNode prev = null;
    while (second != null) {
      ListNode nxt = second.next;
      second.next = prev;
      prev = second;
      second = nxt;
    }

    ListNode first = head;
    second = prev;
    while (second != null) {
      ListNode fnext = first.next;
      ListNode snext = second.next;
      first.next = second;
      second.next = fnext;
      first = fnext;
      second = snext;
    }
  }
}

impl Solution {
  pub fn reorder_list(head: *mut ListNode) {
    if head.is_null() || unsafe { (*head).next.is_null() } {
      return;
    }

    let mut slow = head;
    let mut fast = head;
    unsafe {
      while !(*fast).next.is_null() && !(*(*fast).next).next.is_null() {
        slow = (*slow).next;
        fast = (*(*fast).next).next;
      }
    }

    let mid = slow;
    let mut second = unsafe { (*mid).next };
    unsafe {
      (*mid).next = std::ptr::null_mut();
    }

    let mut prev: *mut ListNode = std::ptr::null_mut();
    while !second.is_null() {
      let nxt = unsafe { (*second).next };
      unsafe {
        (*second).next = prev;
      }
      prev = second;
      second = nxt;
    }

    let mut first = head;
    second = prev;
    while !second.is_null() {
      let fnext = unsafe { (*first).next };
      let snext = unsafe { (*second).next };
      unsafe {
        (*first).next = second;
        (*second).next = fnext;
      }
      first = fnext;
      second = snext;
    }
  }
}

const reorderList = (head: ListNode | null): void => {
  if (!head || !head.next) {
    return;
  }

  let slow: ListNode = head;
  let fast: ListNode = head;
  while (fast.next && fast.next.next) {
    slow = slow.next;
    fast = fast.next.next;
  }

  let second: ListNode | null = slow.next;
  slow.next = null;

  let prev: ListNode | null = null;
  while (second) {
    const nxt: ListNode | null = second.next;
    second.next = prev;
    prev = second;
    second = nxt;
  }

  let first: ListNode | null = head;
  second = prev;
  while (second) {
    const fnext: ListNode | null = first!.next;
    const snext: ListNode | null = second.next;
    first!.next = second;
    second.next = fnext;
    first = fnext;
    second = snext;
  }
};
